#pragma once
#include "model.hpp"
namespace snuw {
inline bool sheetHash(const std::string& value){return value.size()==64&&value.find_first_not_of("0123456789abcdef")==std::string::npos;}
inline const std::vector<std::pair<std::string,std::wstring>> sheetAngles={{"front",L"정면"},{"left",L"왼쪽"},{"right",L"오른쪽"},{"back",L"후면 · 추정"}};
inline void validateReferenceSheet(const json& run){
 if(!run.contains("reference_sheet"))return;auto sheet=run.at("reference_sheet");if(!sheet.is_object()||sheet.value("version",0)!=1||!boardId(str(sheet,"profile"))||!sheetHash(str(sheet,"content_version"))||!sheetHash(str(sheet,"source_sha256"))||!sheet.contains("reviews")||!sheet["reviews"].is_array()||sheet["reviews"].size()!=4||run.at("scenes").size()!=4||run.at("tasks").size()!=4)throw std::runtime_error("참조 시트 기록을 확인하세요.");
 for(int i=0;i<4;i++){auto& scene=run["scenes"][i];auto& task=run["tasks"][i];auto& review=sheet["reviews"][i];auto state=str(review,"state");if(str(scene,"angle")!=sheetAngles[i].first||!scene.value("hypothesis",false)||scene.value("hidden_view",false)!=(i==3)||task.value("scene",-1)!=i||task.value("candidate",-1)!=0||!review.is_object()||(state!="pending"&&state!="approved"&&state!="rejected")||str(review,"note").size()>1000||(state!="pending"&&!sheetHash(str(review,"sha256"))))throw std::runtime_error("참조 시트 각도·검토 기록을 확인하세요.");auto snapshot=scene.at("snapshot"),refs=snapshot.at("_entity_expectations").at("refs"),photos=snapshot.at("project").at("references");if(!refs.is_array()||refs.size()!=1||str(refs[0],"id")!=str(sheet,"profile")||str(refs[0],"kind")!="character"||str(refs[0],"content_version")!=str(sheet,"content_version")||!photos.is_array()||photos.size()!=1||str(photos[0],"source_sha256")!=str(sheet,"source_sha256")||str(photos[0],"source_mode")!=str(run,"mode")||!scene.contains("files")||!scene["files"].is_array()||scene["files"].size()!=1||str(scene["files"][0],"sha")!=str(sheet,"source_sha256")||str(scene["files"][0],"path")!=str(photos[0],"path"))throw std::runtime_error("참조 시트의 원본·프로필 기준이 다릅니다.");}
}
inline bool referenceSheetApproved(const json& run,int index){validateReferenceSheet(run);if(!run.contains("reference_sheet")||index<0||index>=4)return false;auto& task=run["tasks"][index];auto& review=run["reference_sheet"]["reviews"][index];return str(task,"state")=="completed"&&sheetHash(str(task,"sha256"))&&str(review,"state")=="approved"&&str(review,"sha256")==str(task,"sha256");}
inline void reviewReferenceSheet(json& run,int index,bool approved,const std::string& note=""){
 validateReferenceSheet(run);if(!run.contains("reference_sheet")||index<0||index>=4||note.size()>1000)throw std::runtime_error("참조 시트 후보를 선택하세요.");auto& task=run["tasks"][index];if(str(task,"state")!="completed"||!sheetHash(str(task,"sha256")))throw std::runtime_error("완료된 시트 후보를 먼저 확인하세요.");run["reference_sheet"]["reviews"][index]={{"state",approved?"approved":"rejected"},{"sha256",str(task,"sha256")},{"note",note},{"reviewed_at",timestamp()}};
}
struct ReferenceSheetDraft {json scenes,spec;};
inline ReferenceSheetDraft referenceSheetDraft(const json& baseSettings,const std::string& negative,const json& profile,const fs::path& source,const std::string& hash,const std::string& mode){
 auto key=str(profile,"id"),name=str(profile,"name"),version=str(profile,"content_version");if(!boardId(key)||str(profile,"kind")!="character"||name.empty()||name.size()>400||name.find_first_of(":\\/\r\n")!=std::string::npos||!sheetHash(version)||!sheetHash(hash)||(mode!="standard"&&mode!="hardcore")||source.empty())throw std::runtime_error("캐릭터 프로필과 정면 원본을 확인하세요.");
 if(modelId(baseSettings)=="pixel_art")throw std::runtime_error("픽셀아트에는 참조 시트를 사용할 수 없습니다.");auto cfg=baseSettings;cfg["content_mode"]=mode;cfg["consistency_enabled"]=true;cfg["consistency_profile"]=key+" | "+name;cfg["style_profile"]="사용 안 함";cfg["initial_image"]="";cfg["count"]="1";auto state=newState(cfg);state["negative"]=negative;state["project"]["references"]=json::array({{{"path",utf8(source.wstring())},{"role","character"},{"weight",0.6},{"end",0.8},{"source_sha256",hash},{"source_mode",mode}}});applyPromptEdit(state,"character_prompt",L":"+wide(name)+L":");
 state["_entity_expectations"]={{"version",1},{"refs",json::array({{{"id",key},{"kind","character"},{"content_version",version},{"aliases",json::array({name})}}})}};
 ReferenceSheetDraft out;out.scenes=json::array();json reviews=json::array();const char* views[]={"front view","left side profile view, facing left","right side profile view, facing right","back view, facing away"};
 for(int i=0;i<4;i++){auto angle=state;applyPromptEdit(angle,"scene_prompt",wide(std::string(views[i])+", single character, full body, neutral standing pose, plain background"));out.scenes.push_back({{"id",id()},{"page",""},{"name",utf8(sheetAngles[i].second)},{"angle",sheetAngles[i].first},{"hypothesis",true},{"hidden_view",i==3},{"snapshot",panelSnapshot(angle)},{"files",json::array({{{"path",utf8(source.wstring())},{"sha",hash}}})}});reviews.push_back({{"state","pending"},{"sha256",""},{"note",""}});}
 out.spec={{"version",1},{"profile",key},{"profile_name",name},{"content_version",version},{"source_sha256",hash},{"reviews",reviews}};return out;
}
}
